mapper.select:
SELECT dept_name AS deptName, MAX(outpatient_revenue) AS outpatientRevenue, MAX(service_revenue) AS serviceRevenue FROM TR_REV_DEPT WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND dept_name LIKE '%' || #{deptName} || '%'
GROUP BY dept_name ORDER BY dept_name

SELECT doctor_name AS doctorName, dept_name AS deptName, MAX(doctor_benefit) AS doctorBenefit, MAX(service_revenue) AS serviceRevenue FROM TR_REV_DOC WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND dept_name LIKE '%' || #{deptName} || '%'
GROUP BY doctor_name, dept_name ORDER BY dept_name, doctor_name
